read.patch:
diff --git a/internal/engine/relay.go b/internal/engine/relay.go
index 621b866..aa60cf9 100644
--- a/internal/engine/relay.go
+++ b/internal/engine/relay.go
@@ -36,32 +36,38 @@ func getBuffer(size int) (*[]byte, int) {
 	return &b, class
 }

-// tcpToStream allocates scratch only AFTER netpoll reports data. Idle TCP
-// connections retain no copy buffer. Buffer size follows currently queued bytes.
+// tcpToStream returns scratch before waiting in netpoll. Idle TCP connections
+// retain no copy buffer. Successful reads adapt the next scratch size
+// without a second syscall to query queued bytes on every poll attempt.
 func tcpToStream(dst io.Writer, src *net.TCPConn) (int64, error) {
 	raw, err := src.SyscallConn()
 	if err != nil {
 		return 0, err
 	}
 	var total int64
+	readSize := 4096
 	for {
 		var b *[]byte
 		var class, n int
 		var readErr error
 		err = raw.Read(func(fd uintptr) bool {
-			// The nonblocking read itself detects EAGAIN and EOF; peeking
-			// first adds a syscall for every payload without protecting data.
-			available, e := unix.IoctlGetInt(int(fd), unix.TIOCINQ)
-			if e != nil || available <= 0 {
-				available = 32768
-			}
-			b, class = getBuffer(available)
+			// Read directly: ioctl plus read costs two syscalls even when the
+			// socket is empty. Scratch remains borrowed only for this attempt.
+			b, class = getBuffer(readSize)
 			n, readErr = unix.Read(int(fd), *b)
 			if errors.Is(readErr, unix.EAGAIN) || errors.Is(readErr, unix.EINTR) {
 				copyPools[class].Put(b)
 				b = nil
 				return false
 			}
+			if n == len(*b) && readSize < 4096<<(len(copyPools)-1) {
+				// Repeated full reads grow to the existing bounded bulk class.
+				readSize *= 2
+			} else if n > 0 && n <= readSize/4 && readSize > 4096 {
+				// Quarter-full reads shrink one class; hysteresis avoids
+				// bouncing between adjacent classes on ordinary partial reads.
+				readSize /= 2
+			}
 			return true
 		})
 		if b != nil {
diff --git a/internal/engine/relay_test.go b/internal/engine/relay_test.go
index 53bc91f..28c5dc2 100644
--- a/internal/engine/relay_test.go
+++ b/internal/engine/relay_test.go
@@ -269,3 +269,63 @@ func BenchmarkTCPToStream(b *testing.B) {
 		b.Fatalf("transferred %d bytes != expected %d", n, totalBytes)
 	}
 }
+
+// TestTCPToStreamVaryingBursts exercises scratch growth/shrink while preserving
+// exact bytes and EOF. TCP may coalesce writes; the relay must not depend on the
+// sender's chunk boundaries or a queued-byte ioctl to size its next read.
+func TestTCPToStreamVaryingBursts(t *testing.T) {
+	listener, err := net.ListenTCP("tcp", &net.TCPAddr{IP: net.IPv4(127, 0, 0, 1)})
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer listener.Close()
+	local, err := net.DialTCP("tcp", nil, listener.Addr().(*net.TCPAddr))
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer local.Close()
+	source, err := listener.AcceptTCP()
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer source.Close()
+	if err := local.SetDeadline(time.Now().Add(10 * time.Second)); err != nil {
+		t.Fatal(err)
+	}
+	if err := source.SetDeadline(time.Now().Add(10 * time.Second)); err != nil {
+		t.Fatal(err)
+	}
+	var want bytes.Buffer
+	for repeat := 0; repeat < 32; repeat++ {
+		for _, size := range []int{1, 4095, 4096, 8192, 16384, 65536, 5, 131072, 65} {
+			for offset := 0; offset < size; offset++ {
+				want.WriteByte(byte(repeat*31 + offset))
+			}
+		}
+	}
+	done := make(chan error, 1)
+	go func() {
+		payload := want.Bytes()
+		for len(payload) > 0 {
+			// An intentionally awkward write length crosses every scratch class.
+			n, writeErr := local.Write(payload[:min(len(payload), 17003)])
+			payload = payload[n:]
+			if writeErr != nil {
+				done <- writeErr
+				return
+			}
+		}
+		done <- local.CloseWrite()
+	}()
+	var got bytes.Buffer
+	n, err := tcpToStream(&got, source)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := <-done; err != nil {
+		t.Fatal(err)
+	}
+	if n != int64(want.Len()) || !bytes.Equal(got.Bytes(), want.Bytes()) {
+		t.Fatalf("adaptive read lost or changed bytes: accepted=%d got=%d want=%d", n, got.Len(), want.Len())
+	}
+}
